import catalog from './catalog.gen.json' with { type: 'json' };

export type Kind = 'formula' | 'cask';

export type Package = {
  kind: Kind;
  slug: string;
  description: string;
  installs: number;
};

type Category = {
  name: string;
  packages: Package[];
};

// Generated by `vpr catalog:sync` from scripts/catalog.config.ts, ranked by Homebrew installs.
export const CATALOG = catalog as Category[];

export const PACKAGES: readonly Package[] = CATALOG.flatMap((category) => category.packages);
